CREATE TABLE IF NOT EXISTS agents(id TEXT PRIMARY KEY,name TEXT NOT NULL,model TEXT NOT NULL,instructions TEXT NOT NULL, role TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 1, thread_limit INTEGER NOT NULL DEFAULT 2, tool_budget INTEGER NOT NULL DEFAULT 90, backup_model TEXT NOT NULL DEFAULT '', provider_account TEXT NOT NULL DEFAULT '', runtime TEXT NOT NULL DEFAULT 'api') STRICT;
CREATE TABLE IF NOT EXISTS turns(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,agent TEXT NOT NULL REFERENCES agents(id),text TEXT NOT NULL,reply TEXT,status TEXT NOT NULL CHECK(status IN('queued','running','done','failed','interrupted','cancelled')),error TEXT,created TEXT NOT NULL,tool_budget_used INTEGER NOT NULL DEFAULT 0,tool_budget_stopped INTEGER NOT NULL DEFAULT 0, thread TEXT REFERENCES threads(id), channel TEXT REFERENCES channels(id), attachments TEXT NOT NULL DEFAULT '[]', parent TEXT REFERENCES turns(id)) STRICT;
CREATE INDEX IF NOT EXISTS turns_agent_seq ON turns(agent,seq);
CREATE TABLE IF NOT EXISTS threads(id TEXT PRIMARY KEY,agent TEXT NOT NULL REFERENCES agents(id),name TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,archived INTEGER NOT NULL DEFAULT 0,deleted INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE IF NOT EXISTS channels(id TEXT PRIMARY KEY,name TEXT NOT NULL,instructions TEXT NOT NULL,lead TEXT REFERENCES agents(id),revision INTEGER NOT NULL DEFAULT 1,archived INTEGER NOT NULL DEFAULT 0) STRICT;
